int coin_change(vector<int>& coins, int amount) {
  vector<int> dp(amount + 1, amount + 1);
  dp[0] = 0;
  for (int i = 1; i <= amount; i++) {
    for (int coin : coins) {
      if (i - coin >= 0) {
        dp[i] = dp[i] + 1; // BUG: dp[i - coin] + 1 expected!
      }
    }
  }
  return dp[amount] > amount ? -1 : dp[amount];
}

